begin
  foreach team in array selected_teams loop
    if not (templates ? team) then raise exception 'Unknown team: %',team; end if;
    select * into previous from public.wlf_forms where category=team for update;
    if not found then raise exception 'Run UPDATE_V220.sql first'; end if;
    if previous.schema is distinct from templates->team then
      insert into wlf_private.v220_import_audit(item,decision,before_state)
        values('manual-support:'||team||':'||previous.revision,'workbook template explicitly applied',to_jsonb(previous));
      update public.wlf_forms set schema=templates->team,revision=revision+1 where category=team;
    end if;
  end loop;
end
